/**
 * Banner. A raised strip seated on the chassis with
 * a tone pip at its left edge. Tone comes from the accent ramp and the
 * neutrals — Echo has one accent, so severity is carried by LUMINANCE and the
 * pip, not by inventing red/amber/green hues the theme does not own.
 * Composes var(--echo-*).
 */
.echo-banner {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--echo-space-7);
  padding: var(--echo-space-6) var(--echo-space-7);
  border-radius: var(--echo-radius-lg);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  /*
   * A piece of the DEVICE, not a generic alert (2026-09-18, after the original
   * ECHO Kit). A molded status strip: plastic lit from the key angle, a domed
   * LED seated in a recessed well, and an LCD tag that names the tone. The
   * flat translucent plate it replaced read as a placeholder.
   *
   * The drop shadow is short and soft on purpose — the strip sits on the
   * chassis, it does not float over it, so a stack of banners never reads as
   * a stack of buttons.
   */
  background: linear-gradient(
    155deg,
    color-mix(in oklab, var(--echo-cap) 78%, var(--echo-cap-highlight)) 0%,
    var(--echo-cap) 40%,
    color-mix(in oklab, var(--echo-cap) 55%, var(--echo-surface)) 100%
  );
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.08 * var(--echo-gloss, 1))),
    inset 0 -2px 6px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.35 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 1px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.35 * var(--echo-shade, 1) * 100%), transparent),
    0 6px 14px -8px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

/* The recessed well the status LED sits in. */
.echo-banner__well {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: var(--echo-radius-full);
  background: var(--echo-drawn-glass, linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%));
  box-shadow:
    inset 0 2px 4px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

/*
 * The LCD tag: the tone, spelled out on a recessed screen. Severity in WORDS,
 * on top of the shape — the one cue that needs neither colour nor shape
 * vision. Lit tones glow on the glass; quiet tones stay unlit ink.
 */
.echo-banner__tag {
  flex-shrink: 0;
  padding: var(--echo-space-2) var(--echo-space-5);
  border-radius: var(--echo-radius-sm);
  font-family: var(--echo-font-lcd, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-xs);
  font-weight: var(--echo-weight-semibold, 600);
  line-height: var(--echo-leading-tight, 1.25);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: uppercase;
  white-space: nowrap;
  color: var(--echo-text-dim);
  background: var(--echo-drawn-glass, linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%));
  box-shadow:
    inset 0 2px 4px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.85 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.04 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

.echo-banner[data-tone="warn"] .echo-banner__tag {
  color: var(--echo-text);
}

.echo-banner[data-tone="active"] .echo-banner__tag,
.echo-banner[data-tone="danger"] .echo-banner__tag {
  color: var(--echo-accent-ink, var(--echo-accent-glow));
  text-shadow: 0 0 8px color-mix(in oklab, var(--echo-lcd-glow) 55%, transparent);
}

.echo-banner__pip,
.echo-banner__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--echo-text-dim);
}

/*
 * The tone pip.
 *
 * What was wrong: `info` and `warn` were the same banner. The only difference
 * between them was an 8px pip stepping from `text-dim` to `accent-2` — ΔE
 * 0.105 normally, 0.029 under protanopia, 0.026 in greyscale, 1.10:1 in
 * luminance. Four tones, two of which nobody could tell apart.
 *
 * Echo derives every tone from ONE seed hue, and that is worth keeping: it is
 * why the library is structurally immune to the classic red/green failure. But
 * a system that has spent its hue cannot then ask hue to carry severity. The
 * measurement is unambiguous — across the four shipped seeds the best any two
 * pip colours can do is ΔE 0.071-0.113 for info/active, against the 0.15 floor.
 * Colour alone CANNOT do this job here.
 *
 * So each tone gets its own SHAPE, and the shape is load-bearing rather than
 * decorative:
 *
 *   info    hollow ring   — a condition, not an event
 *   active  filled + bloom — lit
 *   warn    triangle      — the one shape every reader already reads as caution
 *   danger  square        — plus the repainted strip it already had
 *
 * That survives protanopia, deuteranopia, tritanopia, greyscale, and a
 * monochrome printout, because none of it is a hue.
 */
.echo-banner__pip {
  box-sizing: border-box;
  width: 10px;
  height: 10px;
  border-radius: var(--echo-radius-full);
  background: var(--echo-text-dim);
}

/* info — hollow. Nothing is lit; there is only something to know. */
.echo-banner[data-tone="info"] .echo-banner__pip {
  background: transparent;
  border: var(--echo-border-fine, 1.5px) solid var(--echo-text-dim);
}

.echo-banner__icon svg {
  width: var(--echo-icon-md, 16px);
  height: var(--echo-icon-md, 16px);
}

/* active — a filled, lit disc: the library's one lit accent, no halo. */
.echo-banner[data-tone="active"] .echo-banner__pip {
  width: 12px;
  height: 12px;
  /* Domed: a specular point up-left, the lit body, a darker skirt. */
  background: radial-gradient(
    circle at 35% 28%,
    color-mix(in oklab, var(--echo-text) 80%, transparent) 0%,
    var(--echo-accent-glow) 46%,
    var(--echo-primary-cap-base) 100%
  );
  box-shadow: inset 0 -1px 1px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.3 * var(--echo-shade, 1) * 100%), transparent), inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

.echo-banner[data-tone="active"] .echo-banner__icon {
  color: var(--echo-primary-cap-top);
}

/*
 * warn — a triangle, at the top of the accent ramp.
 *
 * The shape is the signal. `accent-1` is the lightest stop, which buys what
 * luminance separation the single hue still allows on top of it.
 */
.echo-banner[data-tone="warn"] .echo-banner__pip {
  width: 12px;
  height: 11px;
  border: 0;
  border-radius: 0;
  background: var(--echo-text);
  clip-path: polygon(50% 0%, 100% 100%, 0% 100%);
  box-shadow: none;
}

/*
 * danger — the repainted strip, plus a structural edge.
 *
 * The repaint alone is not enough, and measuring it is how we know: the
 * `accent-5` strip is ΔE 0.047 from an ordinary `cap` strip under protanopia
 * on the Raspberry seed. A protanope sees deep raspberry as very dark, which
 * lands it right on top of the chassis grey. It is tempting to call danger
 * "genuinely distinct" on the strength of its normal-vision appearance and its
 * own 5.18:1 text, but under simulation that does not hold.
 *
 * No ramp stop fixes it. One dark enough to carry the light label (accent-5/6)
 * is too close to the cap under CVD; one far enough from the cap (accent-3)
 * cannot carry the label. So severity is carried structurally instead — a 4px
 * bar down the leading edge, which no colour-vision deficiency can remove —
 * on top of the square pip and the repaint.
 */
/*
 * danger — carried STRUCTURALLY: a 4px lit leading edge (load-bearing — see
 * state-signals.test.ts: the colour alone is ΔE 0.047 under protanopia) and a
 * square pip. The surface only takes a faint wash of the lit accent from that
 * edge. It used to repaint the whole strip in the saturated accent with a glow,
 * which shouted at every reader to say what the edge and the square already
 * said to all of them.
 */
.echo-banner[data-tone="danger"] {
  border-inline-start: var(--echo-border-heavy, 4px) solid var(--echo-primary-cap-mid);
  padding-inline-start: var(--echo-space-6);
  background: linear-gradient(
    90deg,
    color-mix(in oklch, var(--echo-primary-cap-mid) 22%, var(--echo-cap)) 0%,
    var(--echo-cap) 55%,
    color-mix(in oklab, var(--echo-cap) 55%, var(--echo-surface)) 100%
  );
}

/* danger — a square, lit. */
.echo-banner[data-tone="danger"] .echo-banner__pip {
  border: 0;
  border-radius: var(--echo-radius-xs);
  background: var(--echo-primary-cap-mid);
  box-shadow: var(--echo-shadow-edge, inset 0 1px 0 rgb(255 255 255 / calc(0.4 * var(--echo-gloss, 1))));
}

.echo-banner__body {
  flex: 1;
  min-width: 0;
}

.echo-banner__title {
  /* Long content wraps rather than pushing its container open. */
  overflow-wrap: anywhere;
  font-size: var(--echo-text-sm);
  font-weight: var(--echo-weight-bold, 700);
  line-height: var(--echo-leading-tight, 1.25);
  color: var(--echo-text);
}

.echo-banner__text {
  /* Long content wraps rather than pushing its container open. */
  overflow-wrap: anywhere;
  margin-top: var(--echo-space-1);
  font-size: var(--echo-text-xs);
  line-height: var(--echo-leading-body, 1.55);
  color: var(--echo-text-dim);
}

.echo-banner__dismiss {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: var(--echo-radius-sm);
  cursor: pointer;
  color: var(--echo-text-dim);
  background: transparent;
  transition:
    color var(--echo-duration-tick) ease,
    background var(--echo-duration-tick) ease;
}

.echo-banner__dismiss svg {
  width: var(--echo-icon-xs, 12px);
  height: var(--echo-icon-xs, 12px);
}

@media (hover: hover) {
  .echo-banner__dismiss:hover {
    color: var(--echo-text);
    background: color-mix(in oklab, var(--echo-cast-ink, black) calc(0.28 * var(--echo-shade, 1) * 100%), transparent);
  }
}

.echo-banner__dismiss:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow:
    0 0 0 2px var(--echo-cap),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow));
}

@media (prefers-reduced-motion: reduce) {
  .echo-banner__dismiss {
    transition: none;
  }
}

/*
 * WCAG 2.2 2.5.8 — a target must be at least 24x24 CSS px.
 *
 * Expanded with a centred pseudo-element rather than by growing the control:
 * the visual size IS the design, and no component in the library used hit-area
 * expansion before this, so every target was exactly as big as it looked.
 * `max(100%, 24px)` keeps the expansion a floor — a target already larger than
 * 24px is untouched.
 */
.echo-banner__dismiss {
  position: relative;
  /* Declares a deliberate 24px target pad; see tests/helpers/layout.ts. */
  --echo-hit-area: 24px;
}

.echo-banner__dismiss::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: max(100%, 24px);
  height: max(100%, 24px);
  transform: translate(-50%, -50%);
}

/*
 * Coarse-pointer targets.
 *
 * These already clear WCAG 2.2 2.5.8's 24px. This is the 44px both
 * platform guidelines use — a fingertip rather than conformance. Gated on
 * `@media (pointer: coarse)`, so the desktop rendering does not move.
 *
 * Where a control's visual size is the design (a 24px checkbox, a 10px pip),
 * the target is grown with the same transparent pseudo-element as the 24px minimum,
 * not by growing the control.
 */
@media (pointer: coarse) {
  .echo-banner__dismiss {
    --echo-hit-area: 44px;
  }

  .echo-banner__dismiss::after {
    width: max(100%, 44px);
    height: max(100%, 44px);
  }
}

/**
 * Banner — a persistent inline message strip.
 *
 * Distinct from Toast: a Toast is transient and reports something that just
 * happened; a Banner stays, and describes a condition that is still true.
 *
 * a11y: a banner rendered with the page is ordinary content and gets NO live
 * region — announcing it on load would interrupt for something the reader
 * will reach anyway. Pass `live` when the banner APPEARS in response to
 * something, which is the only case worth interrupting for.
 *
 * Static; consumes only var(--echo-*) via banner.css.
 */
import type { HTMLAttributes, ReactNode } from "react";
import type { EchoTone } from "echo-ui-core/types";
import "./banner.css";

/**
 * Banner carries the whole status vocabulary. `EchoTone` is the one
 * list; the alias stays so the name a consumer imports does not change.
 */
export type BannerTone = EchoTone;

export interface BannerProps extends HTMLAttributes<HTMLDivElement> {
  title: string;
  children?: ReactNode;
  tone?: BannerTone;
  /** Leading icon. Decorative — the title carries the meaning. */
  icon?: ReactNode;
  /** Render a dismiss control. */
  onDismiss?: () => void;
  /**
   * The LCD tag on the right. Defaults to the tone in words (Info / Live /
   * Warn / Error); pass your own short word, or `false` to hide it.
   */
  tag?: string | false;
  /** Accessible name for the dismiss control. Defaults to "Dismiss" plus the title. */
  dismissLabel?: string;
  /**
   * Announce when the banner appears dynamically. Danger becomes an alert
   * (interrupts); everything else becomes a polite status.
   */
  live?: boolean;
}

const TONE_TAG: Record<BannerTone, string> = {
  info: "Info",
  active: "Live",
  warn: "Warn",
  danger: "Error",
};

export function Banner({
  title,
  children,
  tone = "info",
  icon,
  tag,
  onDismiss,
  dismissLabel,
  live = false,
  className,
  ...rest
}: BannerProps) {
  const liveProps = live
    ? ({ role: tone === "danger" ? "alert" : "status" } as const)
    : ({} as const);

  return (
    <div
      className={["echo-banner", className].filter(Boolean).join(" ")}
      data-tone={tone}
      {...liveProps}
      {...rest}
    >
      <span className="echo-banner__well" aria-hidden="true">
        {icon ? (
          <span className="echo-banner__icon">{icon}</span>
        ) : (
          <span className="echo-banner__pip" />
        )}
      </span>
      <div className="echo-banner__body">
        <div className="echo-banner__title">{title}</div>
        {children ? <div className="echo-banner__text">{children}</div> : null}
      </div>
      {tag === false ? null : <span className="echo-banner__tag">{tag ?? TONE_TAG[tone]}</span>}
      {onDismiss ? (
        <button
          type="button"
          className="echo-banner__dismiss"
          onClick={onDismiss}
          aria-label={dismissLabel ?? `Dismiss ${title}`}
        >
          <svg viewBox="0 0 12 12" aria-hidden="true" focusable="false">
            <path d="M3 3l6 6M9 3l-6 6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
          </svg>
        </button>
      ) : null}
    </div>
  );
}
